\title{A Sharp Turán--Caro--Wei Lower Bound on the Independence Number}
\author{Aristotle}
\date{2026-06-30}

\begin{document}
\maketitle

\begin{abstract}
We give a complete, self-contained development of the classical lower bound on
the independence number of a finite simple graph in terms of its order and size.
The central result states that every graph with $n$ vertices and $m$ edges
contains an independent set of size at least $n^2/(2m+n)$. We prove this via the
sharper vertex-weighted bound of Caro and Wei---that some independent set $S$
satisfies $\sum_{v} 1/(\deeg(v)+1) \le |S|$---combined with the handshake
identity $\sum_v \deeg(v) = 2m$ and the arithmetic--harmonic mean inequality
(a corollary of Cauchy--Schwarz). We also examine, and refute, the frequently
cited bound $n^2/(4m)$: it is the output of the probabilistic deletion method but
is valid only when $n \le 2m$, failing dramatically for sparse graphs (for
$n=100$, $m=1$ it claims an independent set of $2500$ vertices in a $100$-vertex
graph). The bound $n^2/(2m+n)$ is always valid, never exceeds $n$, coincides with
Tur\'an's extremal value on disjoint unions of equal cliques, and strictly
improves on $n^2/(4m)$ exactly in the regime where the latter is even legal.
\end{abstract}

\section{Introduction}

Let $G$ be a finite simple graph with vertex set $V$, $|V| = n$, and edge set of
cardinality $m$. A set $S \subseteq V$ is \emph{independent} if no two of its
vertices are adjacent. The \emph{independence number} $\alpha(G)$ is the maximum
size of an independent set. Computing $\alpha(G)$ exactly is NP-hard, but strong
and universally valid \emph{lower} bounds are available and have been central to
extremal and probabilistic graph theory since the mid-twentieth century. The
cleanest such guarantee involves only the order $n$ and the size $m$.

\begin{theorem}[Tur\'an / Caro--Wei bound]\label{thm:main}
Every finite simple graph with $n$ vertices and $m$ edges satisfies
\[
  \alpha(G) \;\ge\; \frac{n^2}{2m+n}.
\]
\end{theorem}

The argument factors into three independent, elementary components: a
vertex-weighted refinement (Theorem~\ref{thm:carowei}, Caro--Wei); the handshake
identity (Lemma~\ref{lem:handshake}); and the arithmetic--harmonic mean
inequality (Lemma~\ref{lem:amhm}). A secondary contribution is a careful analysis
of the widely quoted bound $n^2/(4m)$, which we show is false in general.

\section{Definitions and notation}

Throughout, $G = (V,E)$ is a finite simple graph: $V$ is finite and adjacency is a
symmetric, irreflexive relation, written $u \sim v$.

\begin{definition}
The \emph{order} is $n = |V|$ and the \emph{size} is $m = |E|$. The \emph{degree}
of $v$ is $\deeg(v) = |\{u : u \sim v\}|$. A set $S \subseteq V$ is
\emph{independent} if $u \not\sim v$ for all distinct $u,v \in S$, and
$\alpha(G) = \max\{|S| : S \text{ independent}\}$. For $W \subseteq V$, the
\emph{relative degree} is $\deeg_W(v) = |\{u \in W : v \sim u\}|$; note
$\deeg_V(v) = \deeg(v)$.
\end{definition}

\section{The handshake identity and an edge bound}

\begin{lemma}[Handshake identity, weighted form]\label{lem:handshake}
For every finite simple graph, $\displaystyle\sum_{v \in V}\big(\deeg(v)+1\big) = 2m + n.$
\end{lemma}

\begin{proof}[Proof sketch]
Each edge contributes $1$ to the degree of each of its two endpoints, so
$\sum_v \deeg(v) = 2m$. Adding $\sum_v 1 = n$ gives the claim.
\end{proof}

\begin{lemma}[Edge bound]\label{lem:edgebound}
For every finite simple graph, $2m + n \le n^2$.
\end{lemma}

\begin{proof}[Proof sketch]
A simple graph has $m \le \binom{n}{2} = n(n-1)/2$, so $2m \le n^2 - n$ and hence
$2m+n \le n^2$.
\end{proof}

Lemma~\ref{lem:edgebound} ensures $n^2/(2m+n) \ge 1$, so Theorem~\ref{thm:main} is
never vacuous.

\section{The Caro--Wei vertex-weighted bound}

\begin{theorem}[Caro--Wei]\label{thm:carowei}
Every finite simple graph $G$ contains an independent set $S$ with
\[
  \sum_{v \in V} \frac{1}{\deeg(v)+1} \;\le\; |S|.
\]
\end{theorem}

We prove a localized version, from which Theorem~\ref{thm:carowei} follows by
taking $W = V$.

\begin{lemma}[Degree under deletion]\label{lem:degdel}
For $W \subseteq V$, $v_0 \in W$, and any $u \in V$,
\[
  \deeg_W(u) = \deeg_{W \setminus \{v_0\}}(u) + \indicator{u \sim v_0}.
\]
\end{lemma}

\begin{proof}[Proof sketch]
The neighbors of $u$ in $W$ are exactly those in $W \setminus \{v_0\}$ together
with $v_0$ when $u \sim v_0$; counting gives the identity.
\end{proof}

\begin{lemma}[Localized Caro--Wei]\label{lem:localcw}
For every $W \subseteq V$ there is an independent set $S \subseteq W$ with
$\sum_{v \in W} 1/(\deeg_W(v)+1) \le |S|$.
\end{lemma}

\begin{proof}[Proof sketch]
Strong induction on $|W|$. If $W = \varnothing$, take $S = \varnothing$.
Otherwise pick $v_0 \in W$ of maximum relative degree
$d_0 = \deeg_W(v_0)$. If $d_0 = 0$, then $W$ is independent and each term equals
$1$, so $S = W$ works. If $d_0 \ge 1$, apply the inductive hypothesis to
$W' = W \setminus \{v_0\}$ to get independent $S \subseteq W'$ with
$\sum_{v \in W'} 1/(\deeg_{W'}(v)+1) \le |S|$. It suffices to show
$\sum_{v \in W} 1/(\deeg_W(v)+1) \le \sum_{v \in W'} 1/(\deeg_{W'}(v)+1)$.
By Lemma~\ref{lem:degdel}, for a neighbor $u$ of $v_0$ in $W'$,
\[
  \frac{1}{\deeg_{W'}(u)+1} - \frac{1}{\deeg_W(u)+1}
  = \frac{1}{(\deeg_{W'}(u)+1)(\deeg_{W'}(u)+2)} \ge \frac{1}{d_0(d_0+1)},
\]
the inequality because $v_0$ has maximum degree, so $\deeg_{W'}(u)+1 \le d_0$.
Summing over the $d_0$ neighbors of $v_0$ in $W'$ gives a total gain of at least
$d_0 \cdot \tfrac{1}{d_0(d_0+1)} = \tfrac{1}{d_0+1} = \tfrac{1}{\deeg_W(v_0)+1}$,
exactly the weight of the single term ($v_0$) present in $W$ but absent in $W'$.
This closes the induction.
\end{proof}

\section{The arithmetic--harmonic mean inequality}

\begin{lemma}[Arithmetic--harmonic mean inequality]\label{lem:amhm}
For positive reals $f_1,\dots,f_n$,
$\displaystyle \frac{n^2}{\sum_{i} f_i} \le \sum_{i} \frac{1}{f_i}.$
\end{lemma}

\begin{proof}[Proof sketch]
By Cauchy--Schwarz applied to $\sqrt{f_i}$ and $1/\sqrt{f_i}$,
\[
  n^2 = \Big(\sum_i \sqrt{f_i}\cdot \tfrac{1}{\sqrt{f_i}}\Big)^2
  \le \Big(\sum_i f_i\Big)\Big(\sum_i \tfrac{1}{f_i}\Big).
\]
Divide by $\sum_i f_i > 0$.
\end{proof}

\section{Proof of the main theorem}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
By Theorem~\ref{thm:carowei} there is an independent set $S$ with
$\sum_v 1/(\deeg(v)+1) \le |S|$. By Lemma~\ref{lem:amhm} with
$f_v = \deeg(v)+1 > 0$ and the handshake identity (Lemma~\ref{lem:handshake}),
\[
  \frac{n^2}{2m+n} = \frac{n^2}{\sum_v(\deeg(v)+1)}
  \le \sum_v \frac{1}{\deeg(v)+1} \le |S| \le \alpha(G).
\]
Since $|S| \in \mathbb{Z}$, one further has
$\alpha(G) \ge \lceil n^2/(2m+n)\rceil$, and $\alpha(G) \ge 1$ by
Lemma~\ref{lem:edgebound}.
\end{proof}

\section{The folklore bound $n^2/(4m)$ is false}

\subsection{Origin via probabilistic deletion}
Fix $p \in [0,1]$ and sample each vertex independently with probability $p$. The
expected number of retained vertices is $pn$ and of retained edges $p^2 m$;
deleting one endpoint of each retained edge yields an independent set of expected
size at least $pn - p^2 m$. The unconstrained maximizer is $p^\star = n/(2m)$ with
value $n^2/(4m)$.

\subsection{The constraint $p \le 1$ and the failure}
The maximizer $p^\star = n/(2m)$ is a legal probability only if $n \le 2m$. For
$2m < n$ the constrained optimum is at $p=1$, and $n^2/(4m)$ is unattainable.

\begin{example}
For $n=100$, $m=1$, the folklore formula gives $n^2/(4m) = 2500 > n = 100$, which
is impossible. The true bound gives $n^2/(2m+n) = 10000/102 \approx 98.04$, so
$\alpha(G) \ge 99$, which is exactly correct.
\end{example}

\begin{proposition}\label{prop:compare}
For all $n \ge 1$, $m \ge 1$, we have $\dfrac{n^2}{2m+n} \ge \dfrac{n^2}{4m}$ if
and only if $n \le 2m$.
\end{proposition}

\begin{proof}[Proof sketch]
Equal positive numerators, so the fraction inequality reverses the denominator
inequality: $n^2/(2m+n) \ge n^2/(4m) \iff 2m+n \le 4m \iff n \le 2m$.
\end{proof}

Thus the true bound strengthens the folklore bound where the latter is legal and
remains valid where it is not. Moreover $n^2/(2m+n) \le n$ always, so it never
makes an impossible promise.

\section{Sharpness: Tur\'an's extremal graphs}

\begin{proposition}[Tightness]\label{prop:tight}
Let $G$ be the disjoint union of $k$ cliques each of order $r$, so $n = kr$ and
$m = k\binom{r}{2}$. Then $\alpha(G) = k = n^2/(2m+n)$, so
Theorem~\ref{thm:main} holds with equality.
\end{proposition}

\begin{proof}[Proof sketch]
An independent set takes at most one vertex per clique, and exactly one per clique
is independent, so $\alpha(G)=k$. Also $2m+n = kr(r-1)+kr = kr^2 = nr$, hence
$n^2/(2m+n) = (kr)^2/(nr) = k$.
\end{proof}

Every vertex has degree $r-1$, so all Caro--Wei weights equal $1/r$, the total is
$n/r = k$, and the arithmetic--harmonic step is tight because all $f_v$ are equal.

\section{Algorithmic realization}

The proof of Lemma~\ref{lem:localcw} is constructive and yields the
\emph{minimum-degree greedy} algorithm: repeatedly select a vertex of minimum
degree in the current graph, add it to the independent set, and delete it together
with its neighbors. The returned set has size at least
$\sum_v 1/(\deeg(v)+1) \ge n^2/(2m+n)$ and is computed in $O(n+m)$ time with
bucket-by-degree structures.

A randomized alternative is the \emph{random permutation method}: keep each vertex
that precedes all its neighbors in a uniformly random ordering. Vertex $v$ is kept
with probability exactly $1/(\deeg(v)+1)$, the kept set is independent, and its
expected size equals the Caro--Wei sum. Derandomization by conditional
expectations recovers the greedy algorithm.

\section{Applications}

Independent-set guarantees model conflict-free scheduling, interference-free
wireless channel assignment, large minimum-distance codes, and hard-core
configurations in statistical physics. In each case a global existence guarantee
follows from two global counts, with no need to analyze detailed structure.

\section{Discussion and future work}

The development is modular: Caro--Wei (Theorem~\ref{thm:carowei}) is the
substantive combinatorial input, and the passage to the $n,m$-only form is pure
inequality manipulation. Extensions include vertex-weighted and hypergraph
analogues, neighborhood-statistic refinements (Shearer; Ajtai--Koml\'os--Szemer\'edi)
giving $\Omega(\tfrac{n}{d}\log d)$ for triangle-free graphs of average degree
$d$, and approximation-ratio analysis of the greedy algorithm. The methodological
lesson---repairing an ``almost true'' formula $n^2/(4m)$ into an ``always true''
one $n^2/(2m+n)$ by respecting the feasibility constraint $p \le 1$---recurs
throughout the probabilistic method.

\end{document}

