function MIN_DEGREE_GREEDY(V, E):
    build adjacency sets adj[v] for all v in V
    remaining <- V
    S <- empty set
    while remaining is not empty:
        v <- argmin over u in remaining of |adj[u] ∩ remaining|
        S <- S ∪ {v}
        remaining <- remaining \ ({v} ∪ adj[v])
    return S   # independent, |S| >= sum_v 1/(deg v + 1) >= n^2/(2m+n)
